"""Distributed DP noise: the noise is generated by the hospitals, in shares, INSIDE the secure computation.

    released cell  =  exact cell  +  share_1 + share_2 + ... + share_c          (c = number of noise contributors)

Every contributor samples its own share with its own randomness and feeds it into the MPC as a secret-shared input,
so the only value ever opened is the already-noisy cell (see privacy/smpc/protocol.py). The coordinator never sees
an exact aggregate, and the k-threshold is applied to the noisy value (pure post-processing).

COLLUSION TOLERANCE  t
    A coalition that includes t contributors knows their t shares and can subtract them. The shares are therefore
    sized so that the h = c - t shares of the OTHER contributors are already enough on their own:
      * Laplace:  share = Polya(1/h) - Polya(1/h)   ->  any h shares sum to Geometric - Geometric = discrete Laplace
                  exactly (infinite divisibility of the negative binomial); more shares only add independent noise
                  (post-processing), so the guarantee holds against every coalition of <= t contributors.
      * Gaussian: share = N_Z(0, sigma^2 / h)  ->  any h shares give variance sigma^2. The sum of discrete Gaussians
                  is not exactly a discrete Gaussian; Kairouz, Liu & Steinke (ICML 2021) bound its privacy loss by
                      rho <= Delta^2 / (2 sigma^2) + tau * d / 4,    tau = 10 * sum_{k=1}^{h-1} exp(-2 pi^2 s^2 k/(k+1))
                  with s^2 = sigma^2/h the per-share variance and d the number of cells. For our parameters (s >= 1)
                  tau is below 1e-3 and usually below 1e-15; it is charged anyway.
    The price of tolerating t colluders is noise variance x c/h on the released value (x1.5 for c = 3, t = 1).

The PLAN (parameters per output cell) is public: the coordinator builds it, every contributor re-checks it against
its own cap before adding a share (`check`), and the requester sees the resulting noise scale.
"""
from __future__ import annotations

import math
import secrets
from dataclasses import dataclass
from fractions import Fraction
from typing import Literal

import numpy as np

from fedhealth.privacy.dp.accounting import dp_to_zcdp, pure_dp_rho
from fedhealth.privacy.dp.mechanisms import (RandBelow, _conservative_epsilon, sample_discrete_gaussian,
                                             sample_polya)

Mechanism = Literal["laplace", "gaussian", "none"]
MIN_SHARE_SIGMA2 = Fraction(1)          # per-share variance floor: keeps tau negligible (and sigma >= 1/2, as required)


@dataclass(frozen=True)
class CellNoise:
    """Noise parameters of ONE output cell.
    laplace : the TOTAL noise is discrete Laplace  P(x) ~ exp(-|x| * s / t);  each share is Polya(1/h) - Polya(1/h).
    gaussian: each share is N_Z(0, sigma2) - sigma2 is the PER-SHARE variance (a rational number)."""
    sensitivity: int
    s: int = 1
    t: int = 1
    sigma2: Fraction = Fraction(0)


@dataclass(frozen=True)
class NoisePlan:
    mechanism: Mechanism
    contributors: int                    # c: hospitals that each add one share
    honest: int                          # h = c - t: shares that alone already carry the full guarantee
    cells: tuple[CellNoise, ...]
    groups: tuple[tuple[int, int], ...]  # (first cell, n cells) of each independently-budgeted block of cells
    epsilon: float                       # charged to the basic-composition account
    delta: float
    rho: float                           # charged to the zCDP account

    # ------------------------------------------------------------------ sampling (hospital side)
    def sample_share(self, randbelow: RandBelow = secrets.randbelow) -> list[int]:
        """ONE contributor's noise share for every cell."""
        if self.mechanism == "none":
            return [0] * len(self.cells)
        r = Fraction(1, self.honest)
        if self.mechanism == "laplace":
            return [sample_polya(r, c.s, c.t, randbelow) - sample_polya(r, c.s, c.t, randbelow) for c in self.cells]
        return [sample_discrete_gaussian(c.sigma2, randbelow) for c in self.cells]

    def simulate_total(self, size: int, rng: np.random.Generator) -> np.ndarray:
        """Vectorised draw of the TOTAL noise (sum of all c shares), shape (size, n_cells), with numpy's generator.
        Same distribution as summing `sample_share` c times (tests/test_distributed_dp.py checks it); used ONLY by the
        offline evaluation, which needs millions of draws. The services always use the exact samplers above."""
        out = np.zeros((size, len(self.cells)), dtype=np.int64)
        if self.mechanism == "none":
            return out
        for j, c in enumerate(self.cells):
            if self.mechanism == "laplace":
                p = -math.expm1(-c.s / c.t)                         # 1 - a, a = exp(-s/t)
                r_total = self.contributors / self.honest
                out[:, j] = rng.negative_binomial(r_total, p, size) - rng.negative_binomial(r_total, p, size)
            else:
                out[:, j] = _discrete_gaussian_np(float(c.sigma2), size * self.contributors, rng).reshape(size, self.contributors).sum(1)
        return out

    # ------------------------------------------------------------------ what the requester is told
    def total_variance(self, cell: int) -> float:
        c = self.cells[cell]
        if self.mechanism == "laplace":
            a = math.exp(-c.s / c.t)
            return 2 * (self.contributors / self.honest) * a / (1 - a) ** 2
        if self.mechanism == "gaussian":
            return self.contributors * float(c.sigma2)
        return 0.0

    def std(self, cell: int) -> float:
        return math.sqrt(self.total_variance(cell))

    def expected_abs_error(self, cell: int) -> float:
        """E|total noise| on one cell. Laplace-type: the total is X - Y with X, Y ~ NegBin(c/h, 1-a), computed exactly
        (c = h is the discrete Laplace). Gaussian: a sum of discrete Gaussians with sigma^2 >= 1 is Gaussian to
        within rounding, so sd * sqrt(2/pi)."""
        c = self.cells[cell]
        if self.mechanism == "laplace":
            return nb_difference_mean_abs(self.contributors / self.honest, math.exp(-c.s / c.t))
        return self.std(cell) * math.sqrt(2 / math.pi)

    # ------------------------------------------------------------------ re-checking a plan (hospital side)
    def recomputed_rho(self) -> float:
        """rho implied by the cell parameters alone (ignoring what the plan claims)."""
        if self.mechanism == "none":
            return math.inf
        total = 0.0
        for first, n in self.groups:
            cells = self.cells[first:first + n]
            if self.mechanism == "laplace":
                eps = max(c.sensitivity * c.s / c.t for c in cells)   # l1 sensitivity of a block is that of one cell
                total += pure_dp_rho(eps)
            else:
                total += max(gaussian_rho(c.sensitivity, c.sigma2, self.honest, n) for c in cells)
        return total

    # ------------------------------------------------------------------ wire form (common/wire.py: MpcNoise)
    def to_wire(self) -> dict:
        if self.mechanism == "none":
            raise ValueError("an exact computation carries no noise plan")
        return {"mechanism": self.mechanism, "contributors": self.contributors, "honest": self.honest,
                "cells": [{"sensitivity": c.sensitivity, "s": c.s, "t": c.t, "sigma2": str(c.sigma2)} for c in self.cells],
                "groups": [list(g) for g in self.groups], "epsilon": self.epsilon, "delta": self.delta, "rho": self.rho}

    @classmethod
    def from_wire(cls, w) -> "NoisePlan":
        cells = tuple(CellNoise(c.sensitivity, c.s, c.t, Fraction(c.sigma2)) for c in w.cells)
        return cls(w.mechanism, w.contributors, w.honest, cells, tuple(tuple(g) for g in w.groups), w.epsilon, w.delta, w.rho)

    def recomputed_epsilon(self) -> float:
        """Pure-DP epsilon implied by Laplace cell parameters alone: sum over groups of sensitivity * s / t."""
        if self.mechanism != "laplace":
            return math.inf
        return sum(max(c.sensitivity * c.s / c.t for c in self.cells[first:first + n]) for first, n in self.groups)

    def check(self, policy: "NoisePolicy", agg: str, n_cells: int) -> None:
        """Raise ValueError unless this plan protects at least as much as the contributor's own policy demands:
        the budgeted groups are exactly the ones the aggregate has (so no cell escapes the epsilon/rho sum), enough
        honest shares for its collusion tolerance, and no single query above its per-query cap
        (Laplace: pure epsilon; Gaussian: rho of (epsilon, delta) at the cap). A Laplace scale above the hospital's
        cap is refused too: the exact Polya sampler's work grows with the scale, and the hospital answers /prepare at a
        public deadline that must cover that work (hospital/deadlines.py)."""
        if self.mechanism == "none":
            raise ValueError("noise is required")
        if len(self.cells) != n_cells or self.groups != expected_groups(agg, n_cells):
            raise ValueError("the noise plan's groups do not cover the query's output cells")
        if not 1 <= self.honest <= policy.assumed_honest(self.contributors):
            raise ValueError("the noise needs more honest shares than this hospital's collusion tolerance allows")
        if any(c.sensitivity < 1 or (self.mechanism == "gaussian" and c.sigma2 < MIN_SHARE_SIGMA2) for c in self.cells):
            raise ValueError("malformed noise parameters")
        if self.mechanism == "laplace" and self.recomputed_epsilon() > policy.max_epsilon_per_query * (1 + 1e-9):
            raise ValueError(f"noise too small: epsilon {self.recomputed_epsilon():.4g} > cap {policy.max_epsilon_per_query:.4g}")
        if self.mechanism == "gaussian" and self.recomputed_rho() > policy.max_gaussian_rho * (1 + 1e-9):
            raise ValueError(f"noise too small: rho {self.recomputed_rho():.4g} > cap {policy.max_gaussian_rho:.4g}")
        if self.mechanism == "laplace" and max(c.t / c.s for c in self.cells) > policy.max_noise_scale:
            raise ValueError(f"noise scale above the cap {policy.max_noise_scale:g} (the exact sampler's time grows with it)")


@dataclass(frozen=True)
class NoisePolicy:
    """What a HOSPITAL insists on before it adds a share (configs/policy.yaml: distributed_noise)."""
    tolerance: int
    max_epsilon_per_query: float
    max_delta_per_query: float
    max_noise_scale: float = 5e5         # largest per-cell Laplace scale t/s (bounds the sampling work, not privacy)

    @property
    def max_gaussian_rho(self) -> float:
        """The largest rho a Gaussian query may have: (max_epsilon, max_delta)-DP after conversion."""
        if self.max_delta_per_query <= 0:
            return 0.0
        return dp_to_zcdp(self.max_epsilon_per_query, self.max_delta_per_query)

    def assumed_honest(self, contributors: int) -> int:
        """How many of the contributors this hospital is willing to assume honest: a plan whose guarantee needs MORE
        honest shares than that (each share too small) is refused."""
        return contributors - min(self.tolerance, contributors - 1)


def load_noise_policy(path=None) -> NoisePolicy:
    import yaml
    from fedhealth.common.config import config_dir
    with open(path or (config_dir() / "policy.yaml"), encoding="utf-8") as fh:
        raw = yaml.safe_load(fh).get("distributed_noise", {})
    return NoisePolicy(int(raw.get("tolerance", 1)), float(raw.get("max_epsilon_per_query", 2.0)),
                       float(raw.get("max_delta_per_query", 1e-4)), float(raw.get("max_noise_scale", 5e5)))


def nb_difference_mean_abs(r: float, a: float) -> float:
    """E|X - Y| for X, Y iid NegBin(r, 1 - a), via  E|X - Y| = 2 * sum_k F(k) (1 - F(k))  (exact up to truncation at
    mean + 40 sd). For huge scales (SUM with large bounds) the continuous limit, Gamma(r, sqrt(a)/(1-a)), is used:
    E|X - Y| = 2 Gamma(r + 1/2) / (sqrt(pi) Gamma(r)) * scale."""
    mean, sd = r * a / (1 - a), math.sqrt(r * a) / (1 - a)
    kmax = int(mean + 40 * sd) + 50
    if kmax > 5_000_000:
        return 2 * math.exp(math.lgamma(r + 0.5) - math.lgamma(r)) / math.sqrt(math.pi) * math.sqrt(a) / (1 - a)
    k = np.arange(kmax - 1, dtype=float)
    pmf = np.empty(kmax)
    pmf[0] = (1 - a) ** r
    pmf[1:] = pmf[0] * np.cumprod(a * (k + r) / (k + 1))
    cdf = np.cumsum(pmf)
    return float(2 * np.sum(cdf * (1 - cdf)))


def gaussian_rho(l2_sensitivity: int, share_sigma2: Fraction, honest: int, dims: int) -> float:
    """zCDP of the sum of `honest` iid N_Z(0, share_sigma2) noise shares on `dims` cells (Kairouz-Liu-Steinke 2021)."""
    s2 = float(share_sigma2)
    tau = 10 * sum(math.exp(-2 * math.pi ** 2 * s2 * k / (k + 1)) for k in range(1, honest))
    return l2_sensitivity ** 2 / (2 * honest * s2) + tau * dims / 4


def expected_groups(agg: str, n_cells: int) -> tuple[tuple[int, int], ...]:
    """The only grouping a hospital accepts for an aggregate: (first cell, n cells) per budgeted block. COUNT is one
    cell; SUM/AVG are [count] + [total], each budgeted; a HISTOGRAM's bins are one block (one patient is in one bin).
    Fixing it here means a plan cannot leave a cell outside the epsilon/rho sum that the per-query cap checks."""
    if agg == "count" and n_cells == 1:
        return ((0, 1),)
    if agg in ("sum", "avg") and n_cells == 2:
        return ((0, 1), (1, 1))
    if agg == "histogram" and n_cells >= 1:
        return ((0, n_cells),)
    raise ValueError(f"no output shape for {agg!r} with {n_cells} cells")


def make_plan(mechanism: Mechanism, epsilon: float, delta: float, groups: list[tuple[int, int]],
              contributors: int, tolerance: int) -> NoisePlan:
    """Noise for a query whose output cells come in independent blocks: `groups` = [(n_cells, sensitivity), ...].
    The budget is split evenly between blocks (e.g. SUM = [count block, total block]). Within a block the cells are
    disjoint (a histogram): one patient changes ONE cell by at most `sensitivity`, so the block costs the budget once.
    tolerance = how many contributors may collude with the coordinator; it is capped at contributors - 1."""
    honest = contributors - min(max(tolerance, 0), contributors - 1)
    spans, cells, first = [], [], 0
    for n, _ in groups:
        spans.append((first, n))
        first += n
    if mechanism == "none":
        return NoisePlan("none", contributors, honest, tuple(CellNoise(sens) for n, sens in groups for _ in range(n)),
                         tuple(spans), 0.0, 0.0, 0.0)
    g = len(groups)
    if mechanism == "laplace":
        eps_each = _conservative_epsilon(epsilon / g)
        for n, sens in groups:
            cells += [CellNoise(sens, s=eps_each.numerator, t=eps_each.denominator * sens)] * n
        rho = g * pure_dp_rho(float(eps_each))
        return NoisePlan("laplace", contributors, honest, tuple(cells), tuple(spans), epsilon, 0.0, rho)

    rho_target = dp_to_zcdp(epsilon, delta) * (1 - 1e-9)       # the largest rho that still means (epsilon, delta)
    rho = 0.0
    for n, sens in groups:
        sigma2 = sens * sens / (2 * rho_target / g)            # total variance a single block needs
        share = max(Fraction(sigma2 / honest).limit_denominator(10_000) + Fraction(1, 10_000), MIN_SHARE_SIGMA2)
        while gaussian_rho(sens, share, honest, n) > rho_target / g:   # the tau term (tiny shares only): add variance
            share = Fraction(share * Fraction(1001, 1000)).limit_denominator(10_000) + Fraction(1, 10_000)
        cells += [CellNoise(sens, sigma2=share)] * n
        rho += gaussian_rho(sens, share, honest, n)
    return NoisePlan("gaussian", contributors, honest, tuple(cells), tuple(spans), epsilon, delta, rho)


def _discrete_gaussian_np(sigma2: float, size: int, rng: np.random.Generator) -> np.ndarray:
    """Vectorised CKS20 Algorithm 3 (floating-point acceptance) - simulation only."""
    t = math.floor(math.sqrt(sigma2)) + 1
    p = -math.expm1(-1 / t)
    out = np.empty(size, dtype=np.int64)
    filled = 0
    while filled < size:
        k = max(2 * (size - filled), 1024)
        y = rng.geometric(p, k) - rng.geometric(p, k)          # discrete Laplace with scale t
        keep = rng.random(k) < np.exp(-(np.abs(y) - sigma2 / t) ** 2 / (2 * sigma2))
        acc = y[keep][: size - filled]
        out[filled:filled + len(acc)] = acc
        filled += len(acc)
    return out
